import numpy as np
N_x = 40
dx = 1.0 / N_x
xc = np.array([(i + 0.5) * dx for i in range(N_x)])
q_arr = np.zeros(N_x)
for i in range(N_x):
    if 0.25 <= xc[i] < 0.75:
        q_arr[i] = 0.5

def run_model():
    rng = np.random.default_rng(42)
    psi = solve_ugkwp_steady(10.0, 1.0, q_arr.copy(), N_x, 0.2, 50, 4000, 2000, rng)
    return np.round(psi, 6)
assert np.allclose(run_model(), target)
